(function() {
	//#region src/Modules/CrestApps.OrchardCore.Surveys/Assets/js/survey-admin.js
	/**
	* Submits the form a filter select belongs to through its filter button, so the list keeps its other values.
	* @param {HTMLSelectElement} select The filter.
	*/
	function submitFilter(select) {
		const form = select.form;
		if (!form) return;
		const submit = form.querySelector("[name=\"submit.Filter\"]");
		if (submit) submit.click();
		else form.submit();
	}
	/**
	* Copies a text and shows that it was copied on the button.
	* @param {HTMLElement} button The button.
	*/
	async function copy(button) {
		const text = button.dataset.surveyCopy ?? "";
		try {
			await navigator.clipboard.writeText(text);
			button.classList.add("btn-success");
			setTimeout(() => button.classList.remove("btn-success"), 1500);
		} catch {
			window.prompt("", text);
		}
	}
	document.addEventListener("change", (event) => {
		const target = event.target;
		if (target instanceof HTMLSelectElement && target.matches("[data-surveys-list-filter]")) submitFilter(target);
	});
	document.addEventListener("click", (event) => {
		const button = event.target.closest("[data-survey-copy]");
		if (button) {
			event.preventDefault();
			copy(button);
		}
	});
	//#endregion
})();
